    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath
)
{
    NTSTATUS status;

    DriverObject->DriverUnload = UnloadDriver;

    status = IoCreateDevice(DriverObject,
                             0,
                             &DriverObject->DeviceObject,
                             FILE_DEVICE_UNKNOWN,
                             0,
                             FALSE,
                             FILE_ATTRIBUTE_NORMAL,
                             NULL);

    if (!NT_SUCCESS(status)) {
        return status;
    }

    status = IoAttachDeviceToDeviceStack(DriverObject->DeviceObject, &DriverObject->DeviceExtension);

    if (!NT_SUCCESS(status)) {
        IoDeleteDevice(DriverObject->DeviceObject);
        return status;
    }

    return status;
}

void UnloadDriver(PDRIVER_OBJECT DriverObject)
{
    IoDeleteDevice(DriverObject->DeviceObject);
}
```

### Step 3: Attach the Kernel Driver
1. Load the kernel driver using WinDbg.
2. Use the `!devcon` command to attach the driver to a device.

Example command in WinDbg:
```
!devcon attach driver=MyDriver.sys
```

